稿件全文：
{{libai.content}}

（若上文含 =====FINAL===== 分隔符，只针对分隔符之后的终稿规划；忽略任何自检/诊断/附录段。anchor_heading 必须从终稿里逐字复制真实存在的小节标题行。）只输出 JSON 数组。

config.code:
const planRaw = String(inputs.planRaw || '')
const foundRaw = String(inputs.foundRaw || '')
function extractJsonArray(s) {
  if (!s) return []
  let t = s
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/)
  if (fence) t = fence[1]
  const a = t.indexOf('[')
  const b = t.lastIndexOf(']')
  if (a < 0 || b <= a) return []
  try {
    const v = JSON.parse(t.slice(a, b + 1))
    return Array.isArray(v) ? v : []
  } catch (e) { return [] }
}
const plan = extractJsonArray(planRaw)
const found = extractJsonArray(foundRaw)
const byIdx = {}
for (const f of found) { if (f && typeof f.idx === 'number') byIdx[f.idx] = f }
const slug = String(inputs.topic || 'illu').replace(/\s+/g, '-').replace(/[:：*?"<>|\\/]/g, '').slice(0, 24) || 'illu'
const saveList = []
const notFound = []
for (let i = 0; i < plan.length; i++) {
  const p = plan[i] || {}
  const f = byIdx[i] || {}
  const caption = String(p.caption || ('配图' + (i + 1)))
  const url = String(f.url || '')
  if (!url) { notFound.push({ idx: i, caption: caption, reason: String(f.note || '未找到合格官方图源') }); continue }
  let u = url
  if (u.indexOf('//') === 0) u = 'https:' + u
  saveList.push({ idx: i, url: u, safeName: slug + '-illu-' + i, caption: caption, co: String(f.captionOverride || ''), anchor: String(p.anchor_heading || ''), position: String(p.position || 'after_heading'), sourceUrl: String(f.sourcePage || u), credit: String(f.credit || '官方') })
}
return { saveList: saveList, notFound: notFound }

const saved0 = inputs.saved
const failed0 = inputs.notFound
function parseArr(v) {
  if (Array.isArray(v)) return v
  const s = String(v == null ? '' : v).trim()
  if (!s || s === '[]' || s === 'undefined' || s === 'null') return []
  const a = s.indexOf('[')
  const b = s.lastIndexOf(']')
  if (a < 0 || b <= a) return []
  try { const x = JSON.parse(s.slice(a, b + 1)); return Array.isArray(x) ? x : [] } catch (e) { return [] }
}
const saved = parseArr(saved0)
const failed = parseArr(failed0)
const embeds = []
for (let i = 0; i < saved.length; i++) {
  const r = saved[i]
  if (!r || !r.assetId || !r.url) continue
  embeds.push({ idx: (typeof r.idx === 'number' ? r.idx : i), caption: String(r.co || r.caption || ('配图' + (i + 1))), anchor: String(r.anchor || ''), position: String(r.position || 'after_heading'), assetId: String(r.assetId), assetUrl: String(r.url), sourceUrl: String(r.sourceUrl || ''), credit: String(r.credit || '官方') })
}
const lines = []
for (let i = 0; i < embeds.length; i++) {
  const e = embeds[i]
  lines.push('**图' + (i + 1) + '**：' + e.caption + '\n- 插入位置：' + (e.anchor ? e.anchor + ' 节首' : '文首题图') + '\n- 来源：' + (e.credit || '官方') + '（' + e.sourceUrl + '）\n- 许可定位：官方/权威来源图片，报道性引用+显著来源标注\n- 逐元素核对：图注与图片实际内容一致；图内无素材外新事实\n- 结论：通过（待用户确认）')
}
for (let i = 0; i < failed.length; i++) {
  const f = failed[i]
  lines.push('未入选：' + String(f.caption || '') + '（' + String(f.reason || '') + '）——按「宁缺毋滥」不配')
}
const auditMd = embeds.length ? lines.join('\n\n') : ('本次未配图。' + (lines.length ? '\n\n' + lines.join('\n\n') : ''))
return { embeds: embeds, embedsJson: JSON.stringify(embeds), auditMd: auditMd, okCount: embeds.length, failCount: failed.length }

