config.code:
const ws = String(inputs.ws || '')
const libai = String(inputs.libai || '')
const SPLIT = '=====FINAL====='
let final = ''
let diagnosis = ''
const i = libai.indexOf(SPLIT)
if (i >= 0) {
  diagnosis = libai.slice(0, i).trim()
  final = libai.slice(i + SPLIT.length).trim()
} else {
  final = libai.trim()
}
const fallbackUsed = !final
if (!final) final = ws
let wsArticle = ws
let wsAppendix = ''
const m = ws.search(/\n#{1,4}\s*深度自检/)
if (m > 0) {
  wsArticle = ws.slice(0, m).trim()
  wsAppendix = ws.slice(m).trim()
}
if (!wsAppendix) wsAppendix = wsArticle.length < ws.length ? '' : '（写作阶段未输出自检附文）'
const approved = typeof inputs.decision === 'string' && inputs.decision !== 'reject'
const embeds = (approved && Array.isArray(inputs.embeds)) ? inputs.embeds : []
let imgCount = 0
const dropped = []
for (let k = 0; k < embeds.length; k++) {
  const e = embeds[k]
  if (!e || !e.assetUrl) continue
  const tag = '\n\n![' + String(e.caption || '配图').replace(/[\[\]]/g, '」') + '](' + e.assetUrl + ')\n'
  let placed = false
  const lines = final.split('\n')
  if (!e.anchor) {
    let p = 0
    while (p < lines.length && (lines[p].trim().indexOf('#') === 0 || lines[p].trim() === '')) p++
    lines.splice(p, 0, tag)
    final = lines.join('\n')
    placed = true
  } else {
    const target = String(e.anchor).trim()
    for (let li = 0; li < lines.length; li++) {
      if (lines[li].trim() === target) {
        lines.splice(li + 1, 0, tag)
        final = lines.join('\n')
        placed = true
        break
      }
    }
  }
  if (placed) imgCount++
  else dropped.push(String(e.caption || ''))
}
let auditSection = inputs.auditMd ? String(inputs.auditMd) : '（无）'
if (dropped.length) auditSection += '\n\n未嵌入（锚点未命中，宁缺毋滥不硬插）：' + dropped.join('；')
return { final: final, diagnosis: diagnosis || '（未产出诊断段）', appendix: wsAppendix || '（无）', fallbackUsed: fallbackUsed, wsArticle: wsArticle, auditSection: auditSection, imageCount: imgCount }

